import json,hashlib

def canonical(x):return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()
def digest(x):return hashlib.sha256(x).hexdigest()
def project(raw,attestation,registry):
    # attestation is a separately authenticated harness input, not a source claim.
    try:
        text=raw.decode('utf-8'); document=None
        if attestation['kind']!='GOVERNED_TEXT':
            def pairs(items):
                d={}
                for k,v in items:
                    if k in d:raise ValueError('duplicate key')
                    d[k]=v
                return d
            document=json.loads(text,object_pairs_hook=pairs,parse_constant=lambda _: (_ for _ in ()).throw(ValueError('constant')))
            if type(document) is not dict:return {'stage':'RECOGNITION','result':'MALFORMED_SOURCE'}
        candidates=[]
        for r in registry:
            disc=r['discriminator']
            if 'authenticated_kind' in disc:
                hit=attestation['kind']==disc['authenticated_kind'] and document is None
            elif 'field' in disc:hit=document is not None and document.get(disc['field'])==disc['value']
            else:hit=document is not None and all(document.get(k)==v for k,v in disc.items())
            if hit:candidates.append(r)
        if len(candidates)>1:return {'stage':'RECOGNITION','result':'AMBIGUOUS_SOURCE'}
        if not candidates:return {'stage':'RECOGNITION','result':'MALFORMED_SOURCE' if document is not None and 'schema' not in document and 'schema_version' not in document else 'UNSUPPORTED_SOURCE'}
        r=candidates[0]
        if attestation['identity']['domain']!='CONTENT_IDENTITY':return {'stage':'SOURCE_VALIDATION','result':'WRONG_DOMAIN'}
        if attestation['identity']['sha256']!=digest(raw):return {'stage':'SOURCE_VALIDATION','result':'SOURCE_SUBSTITUTED'}
        if attestation['currentness']!='CURRENT':return {'stage':'SOURCE_VALIDATION','result':'STALE_SOURCE'}
        if attestation['class']!=r['id']:return {'stage':'SOURCE_VALIDATION','result':'PROVENANCE_CLASS_MISMATCH'}
        if document is not None and any(k not in document for k in r['required_fields']):return {'stage':'SOURCE_VALIDATION','result':'MISSING_REQUIRED_FIELD'}
        if document is not None and any(type(document[k]).__name__!=t for k,t in r['field_types'].items()):return {'stage':'SOURCE_VALIDATION','result':'WRONG_FIELD_TYPE'}
        values={}
        for selector in attestation['selectors']:
            if document is None:
                if selector!='/raw':return {'stage':'PROFILE_PROJECTION','result':'UNSUPPORTED_TEXT_SELECTOR'}
                value=text
            else:
                value=document
                for token in selector.split('/')[1:]:value=value[int(token)] if type(value) is list else value[token.replace('~1','/').replace('~0','~')]
            values[selector]={'value':value,'selected_value_sha256':digest(canonical(value))}
        body={'schema':'CE02-SOURCE-ENVELOPE-1','source_class':r['id'],'source_identity':attestation['identity'],'source_schema':r['discriminator'],'projection_version':'CE02-1','values':values,'provenance':{'selectors':sorted(attestation['selectors']),'kind':attestation['kind'],'currentness':attestation['currentness']}}
        return {'stage':'OPERATIONAL_PROFILE_PROJECTION','result':'UNSUPPORTED_REQUIRED_SOURCE','source_envelope':body,'identity':{'domain':'CONTENT_IDENTITY','namespace':'ce02-source-envelope-v1','sha256':digest(canonical(body))},'reason':'No authorized source-envelope to existing operational predicate input adapter is defined; do not synthesize proof or trusted profile.'}
    except (KeyError,TypeError,ValueError,UnicodeError,IndexError):return {'stage':'RECOGNITION_OR_PROJECTION','result':'MALFORMED_SOURCE'}
